// Power Query (M) for the R&D Stability Data Platform. Azure Blob Storage is the only source.
// Paste into Power BI Desktop > Get data > Blank query > Advanced editor, then split the "let" bindings into separate queries
// (Reference_*, ObservationCurrent, ObservationFlat, DefectIncidence, PlanProgress, MediaCoverage, AuditLog) or keep as one and reference it.
// Replace <storageaccount>. Authentication: Organizational account (Storage Blob Data Reader) or account key.
// Generated from field_catalog.csv: the pivot below has one column per catalog field, typed. Regenerate when the catalog changes.
let
    Account = "https://<storageaccount>.blob.core.windows.net/",
    Source = AzureStorage.Blobs(Account),
    Curated = Source{[Name = "curated"]}[Data],
    Reference = Source{[Name = "reference"]}[Data],

    // ---- generic NDJSON folder reader: curated/{dataset}/yyyy/mm/dd.ndjson
    ReadFolder = (folder as text) as table =>
        let
            Files = Table.SelectRows(Curated, each Text.StartsWith([Name], folder & "/") and Text.EndsWith([Name], ".ndjson")),
            Lines = Table.AddColumn(Files, "Lines", each Lines.FromBinary([Content], null, null, 65001)),
            Expanded = Table.ExpandListColumn(Table.SelectColumns(Lines, {"Lines"}), "Lines"),
            NonEmpty = Table.SelectRows(Expanded, each [Lines] <> null and [Lines] <> ""),
            Parsed = Table.AddColumn(NonEmpty, "Row", each Json.Document([Lines])),
            Records = Table.FromRecords(Table.Column(Parsed, "Row"), null, MissingField.UseNull)
        in
            Records,

    // ---- reference data (NESTMS / LIMS exports)
    Reference_Projects = Table.FromRecords(Json.Document(Reference{[Name = "projects.json"]}[Content]), null, MissingField.UseNull),
    Reference_Ars = Table.FromRecords(Json.Document(Reference{[Name = "ars.json"]}[Content]), null, MissingField.UseNull),
    Reference_Trials = Table.FromRecords(Json.Document(Reference{[Name = "trials.json"]}[Content]), null, MissingField.UseNull),
    Reference_Variants = Table.FromRecords(Json.Document(Reference{[Name = "variants.json"]}[Content]), null, MissingField.UseNull),
    Reference_Samples = Table.FromRecords(Json.Document(Reference{[Name = "samples.json"]}[Content]), null, MissingField.UseNull),
    Reference_Plans = Table.FromRecords(Json.Document(Reference{[Name = "plans.json"]}[Content]), null, MissingField.UseNull),
    Reference_Users = Table.FromRecords(Json.Document(Reference{[Name = "users.json"]}[Content]), null, MissingField.UseNull),

    // ---- observation header: append-only; the current row per observation is the one with the latest appendedAt
    ObservationHeader = Table.TransformColumnTypes(ReadFolder("observation_header"),
        {{"versionNo", Int64.Type}, {"observedAt", type datetimezone}, {"submittedAt", type datetimezone}, {"reviewedAt", type datetimezone}, {"appendedAt", type datetimezone}, {"mediaCount", Int64.Type}, {"overallResultNA", type logical}}),
    HeaderRanked = Table.AddColumn(
        Table.Group(ObservationHeader, {"observationId"}, {{"Rows", each Table.Sort(_, {{"appendedAt", Order.Descending}}), type table}}),
        "Current", each Table.First([Rows])),
    ObservationCurrent = Table.SelectRows(Table.FromRecords(Table.Column(HeaderRanked, "Current"), null, MissingField.UseNull), each [status] <> "REJECTED"),

    // ---- values for the current versions only
    ObservationValue = Table.TransformColumnTypes(ReadFolder("observation_value"),
        {{"versionNo", Int64.Type}, {"valueNumber", type number}, {"valueBoolean", type logical}, {"isNA", type logical}, {"observedAt", type datetimezone}}),
    CurrentKeys = Table.SelectColumns(ObservationCurrent, {"observationId", "versionNo"}),
    ObservationValueCurrent = Table.Join(ObservationValue, {"observationId", "versionNo"}, CurrentKeys, {"observationId", "versionNo"}, JoinKind.Inner),

    // ---- one column per catalog field (N/A becomes null; booleans and numbers typed)
    FieldCodes = {"product_format", "container_type", "package_volume_ml", "package_fill_height_mm", "sample_storage_orientation", "sample_temperature_at_test", "sample_opened_previously", "shake_protocol", "shake_count", "plan_status", "exclude_from_trend", "exclude_reason", "overall_comments", "lab_source", "lab_lims_reference", "lab_ph", "lab_visc1_value", "lab_visc1_instrument", "lab_visc1_geometry", "lab_visc1_shear_rate", "lab_visc1_temp_c", "lab_visc2_value", "lab_visc2_instrument", "lab_visc2_geometry", "lab_visc2_shear_rate", "lab_visc2_temp_c", "lab_brix", "lab_particle_size_d50_um", "lab_measured_at", "general_overview_photo", "general_empty_bottle_photo", "general_beaker_photo", "general_pour_out_video", "homog_unshaken_homogeneous", "homog_unshaken_appearance", "homog_unshaken_photo", "homog_shaken_test_performed", "homog_shaken_homogeneous", "homog_post_shake_color_change", "homog_post_shake_color_description", "homog_post_shake_color_code", "homog_shaken_photo", "homog_comments", "cream_unsh_present", "cream_unsh_rating", "cream_unsh_layer_measurable", "cream_unsh_layer_thickness_value", "cream_unsh_layer_thickness_unit", "cream_unsh_layer_description", "cream_unsh_layer_color", "cream_unsh_marbling_present", "cream_unsh_minor_spots_present", "cream_unsh_surface_volume_pct", "cream_unsh_pour_exit_time_s", "cream_unsh_photo", "cream_unsh_pour_out_video", "cream_unsh_pour_out_result", "cream_sh_shakes_in", "cream_sh_rating", "cream_sh_result", "cream_sh_residue_type", "cream_sh_residual_pct", "cream_sh_photo", "cream_emulsifier_flag", "cream_rim_dried_residue_present", "cream_rim_residue_fatty", "cream_market_restriction_flag", "cream_review_prompt", "cream_comments", "serum_unsh_present", "serum_unsh_rating", "serum_unsh_measurable", "serum_unsh_value", "serum_unsh_unit", "serum_unsh_pct_package_volume", "serum_unsh_locations", "serum_unsh_clarity", "serum_unsh_color", "serum_unsh_photo", "serum_sh_shakes_in", "serum_sh_rating", "serum_sh_value", "serum_sh_unit", "serum_sh_result", "serum_sh_photo", "serum_gelation_flag", "serum_protein_flag", "serum_resep_check_performed", "serum_resep_hours_after_shake", "serum_resep_present", "serum_resep_rating", "serum_resep_photo", "serum_scale_up_viscosity_warning", "serum_review_prompt", "serum_comments", "sed_unsh_present", "sed_unsh_rating", "sed_unsh_height_value", "sed_unsh_height_unit", "sed_unsh_coverage", "sed_unsh_texture", "sed_measurement_point", "sed_measurement_location", "sed_weight_g", "sed_bottle_cut_to_evaluate", "sed_bottle_coating_present", "sed_unsh_photo", "sed_predominant_type", "sed_prot_review_prompt", "sed_min_appearance", "sed_min_review_prompt", "sed_coc_ring_present", "sed_coc_settling_pct_volume", "sed_coc_review_prompt", "sed_sh_rating", "sed_sh_height_value", "sed_sh_height_unit", "sed_sh_shake_in_extent", "sed_sh_lumps_present", "sed_sh_photo", "sed_composition_test_requested", "sed_comments", "gel_gelled", "gel_type", "gel_too_thick_to_pour", "gel_firmness", "gel_shake_test_performed", "gel_reversibility", "gel_spoilage_related", "gel_observations", "gel_photo", "gel_comments", "nh_rippling_present", "nh_lumps_present", "nh_lumps_severity", "nh_lumps_context", "nh_lumps_size_class", "nh_sieve_used", "nh_sieve_mesh", "nh_curdling_present", "nh_smooth_after_shaking", "nh_spoilage_related", "nh_pour_video", "nh_photo", "nh_comments", "psag_vertical_stripes_present", "psag_stripe_coverage", "psag_photo", "psag_comments", "app_color_change_vs_t0", "app_color_method", "app_color_l", "app_color_a", "app_color_b", "sens_recorded", "sens_texture", "sens_notes", "custom1_name", "custom1_unshaken", "custom1_shaken", "custom2_name", "custom2_unshaken", "custom2_shaken", "custom3_name", "custom3_unshaken", "custom3_shaken", "pwd_caking", "pwd_flowability", "pwd_color_change", "pwd_lumps_present", "pwd_wettability_s", "pwd_dissolution_s", "pwd_foaming", "pwd_photo", "vms_appearance_change", "vms_surface_mottling", "vms_chipping_capping", "vms_hardness_kp", "vms_disintegration_min", "vms_odor_change", "vms_capsule_leakage", "vms_photo"},
    ValueForPivot = Table.AddColumn(ObservationValueCurrent, "v", each if [isNA] = true then null else if [valueBoolean] <> null then Text.From([valueBoolean]) else if [valueNumber] <> null then Text.From([valueNumber]) else [valueText], type text),
    Pivoted = Table.Pivot(Table.SelectColumns(ValueForPivot, {"observationId", "versionNo", "fieldCode", "v"}), FieldCodes, "fieldCode", "v"),
    TypedFlat = Table.TransformColumnTypes(Pivoted,
        {
            {"product_format", type text},
            {"container_type", type text},
            {"package_volume_ml", type number},
            {"package_fill_height_mm", type number},
            {"sample_storage_orientation", type text},
            {"sample_temperature_at_test", type number},
            {"sample_opened_previously", type logical},
            {"shake_protocol", type text},
            {"shake_count", Int64.Type},
            {"plan_status", type text},
            {"exclude_from_trend", type logical},
            {"exclude_reason", type text},
            {"overall_comments", type text},
            {"lab_source", type text},
            {"lab_lims_reference", type text},
            {"lab_ph", type number},
            {"lab_visc1_value", type number},
            {"lab_visc1_instrument", type text},
            {"lab_visc1_geometry", type text},
            {"lab_visc1_shear_rate", type number},
            {"lab_visc1_temp_c", type number},
            {"lab_visc2_value", type number},
            {"lab_visc2_instrument", type text},
            {"lab_visc2_geometry", type text},
            {"lab_visc2_shear_rate", type number},
            {"lab_visc2_temp_c", type number},
            {"lab_brix", type number},
            {"lab_particle_size_d50_um", type number},
            {"lab_measured_at", type datetimezone},
            {"general_overview_photo", type text},
            {"general_empty_bottle_photo", type text},
            {"general_beaker_photo", type text},
            {"general_pour_out_video", type text},
            {"homog_unshaken_homogeneous", type logical},
            {"homog_unshaken_appearance", type text},
            {"homog_unshaken_photo", type text},
            {"homog_shaken_test_performed", type logical},
            {"homog_shaken_homogeneous", type logical},
            {"homog_post_shake_color_change", type logical},
            {"homog_post_shake_color_description", type text},
            {"homog_post_shake_color_code", type text},
            {"homog_shaken_photo", type text},
            {"homog_comments", type text},
            {"cream_unsh_present", type logical},
            {"cream_unsh_rating", type text},
            {"cream_unsh_layer_measurable", type logical},
            {"cream_unsh_layer_thickness_value", type number},
            {"cream_unsh_layer_thickness_unit", type text},
            {"cream_unsh_layer_description", type text},
            {"cream_unsh_layer_color", type text},
            {"cream_unsh_marbling_present", type logical},
            {"cream_unsh_minor_spots_present", type logical},
            {"cream_unsh_surface_volume_pct", type number},
            {"cream_unsh_pour_exit_time_s", type number},
            {"cream_unsh_photo", type text},
            {"cream_unsh_pour_out_video", type text},
            {"cream_unsh_pour_out_result", type text},
            {"cream_sh_shakes_in", type logical},
            {"cream_sh_rating", type text},
            {"cream_sh_result", type text},
            {"cream_sh_residue_type", type text},
            {"cream_sh_residual_pct", type number},
            {"cream_sh_photo", type text},
            {"cream_emulsifier_flag", type logical},
            {"cream_rim_dried_residue_present", type logical},
            {"cream_rim_residue_fatty", type logical},
            {"cream_market_restriction_flag", type logical},
            {"cream_review_prompt", type logical},
            {"cream_comments", type text},
            {"serum_unsh_present", type logical},
            {"serum_unsh_rating", type text},
            {"serum_unsh_measurable", type logical},
            {"serum_unsh_value", type number},
            {"serum_unsh_unit", type text},
            {"serum_unsh_pct_package_volume", type number},
            {"serum_unsh_locations", type text},
            {"serum_unsh_clarity", type text},
            {"serum_unsh_color", type text},
            {"serum_unsh_photo", type text},
            {"serum_sh_shakes_in", type logical},
            {"serum_sh_rating", type text},
            {"serum_sh_value", type number},
            {"serum_sh_unit", type text},
            {"serum_sh_result", type text},
            {"serum_sh_photo", type text},
            {"serum_gelation_flag", type logical},
            {"serum_protein_flag", type logical},
            {"serum_resep_check_performed", type logical},
            {"serum_resep_hours_after_shake", type number},
            {"serum_resep_present", type logical},
            {"serum_resep_rating", type text},
            {"serum_resep_photo", type text},
            {"serum_scale_up_viscosity_warning", type logical},
            {"serum_review_prompt", type logical},
            {"serum_comments", type text},
            {"sed_unsh_present", type logical},
            {"sed_unsh_rating", type text},
            {"sed_unsh_height_value", type number},
            {"sed_unsh_height_unit", type text},
            {"sed_unsh_coverage", type text},
            {"sed_unsh_texture", type text},
            {"sed_measurement_point", type text},
            {"sed_measurement_location", type text},
            {"sed_weight_g", type number},
            {"sed_bottle_cut_to_evaluate", type logical},
            {"sed_bottle_coating_present", type logical},
            {"sed_unsh_photo", type text},
            {"sed_predominant_type", type text},
            {"sed_prot_review_prompt", type logical},
            {"sed_min_appearance", type text},
            {"sed_min_review_prompt", type logical},
            {"sed_coc_ring_present", type logical},
            {"sed_coc_settling_pct_volume", type number},
            {"sed_coc_review_prompt", type logical},
            {"sed_sh_rating", type text},
            {"sed_sh_height_value", type number},
            {"sed_sh_height_unit", type text},
            {"sed_sh_shake_in_extent", type text},
            {"sed_sh_lumps_present", type logical},
            {"sed_sh_photo", type text},
            {"sed_composition_test_requested", type logical},
            {"sed_comments", type text},
            {"gel_gelled", type logical},
            {"gel_type", type text},
            {"gel_too_thick_to_pour", type logical},
            {"gel_firmness", type text},
            {"gel_shake_test_performed", type logical},
            {"gel_reversibility", type text},
            {"gel_spoilage_related", type text},
            {"gel_observations", type text},
            {"gel_photo", type text},
            {"gel_comments", type text},
            {"nh_rippling_present", type logical},
            {"nh_lumps_present", type logical},
            {"nh_lumps_severity", type text},
            {"nh_lumps_context", type text},
            {"nh_lumps_size_class", type text},
            {"nh_sieve_used", type logical},
            {"nh_sieve_mesh", type text},
            {"nh_curdling_present", type logical},
            {"nh_smooth_after_shaking", type logical},
            {"nh_spoilage_related", type text},
            {"nh_pour_video", type text},
            {"nh_photo", type text},
            {"nh_comments", type text},
            {"psag_vertical_stripes_present", type logical},
            {"psag_stripe_coverage", type text},
            {"psag_photo", type text},
            {"psag_comments", type text},
            {"app_color_change_vs_t0", type text},
            {"app_color_method", type text},
            {"app_color_l", type number},
            {"app_color_a", type number},
            {"app_color_b", type number},
            {"sens_recorded", type logical},
            {"sens_texture", type text},
            {"sens_notes", type text},
            {"custom1_name", type text},
            {"custom1_unshaken", type text},
            {"custom1_shaken", type text},
            {"custom2_name", type text},
            {"custom2_unshaken", type text},
            {"custom2_shaken", type text},
            {"custom3_name", type text},
            {"custom3_unshaken", type text},
            {"custom3_shaken", type text},
            {"pwd_caking", type text},
            {"pwd_flowability", type text},
            {"pwd_color_change", type text},
            {"pwd_lumps_present", type logical},
            {"pwd_wettability_s", type number},
            {"pwd_dissolution_s", type number},
            {"pwd_foaming", type text},
            {"pwd_photo", type text},
            {"vms_appearance_change", type text},
            {"vms_surface_mottling", type text},
            {"vms_chipping_capping", type logical},
            {"vms_hardness_kp", type number},
            {"vms_disintegration_min", type number},
            {"vms_odor_change", type text},
            {"vms_capsule_leakage", type logical},
            {"vms_photo", type text}
        }),
    ObservationFlat = Table.NestedJoin(ObservationCurrent, {"observationId", "versionNo"}, TypedFlat, {"observationId", "versionNo"}, "Flat", JoinKind.LeftOuter),
    ObservationFlatExpanded = Table.ExpandTableColumn(ObservationFlat, "Flat", FieldCodes, FieldCodes),

    // ---- defect incidence: 1 = present, 0 = assessed and absent, null = not assessed
    Flags1 = Table.AddColumn(ObservationFlatExpanded, "HOMOG", each if [homog_unshaken_homogeneous] = null then null else if [homog_unshaken_homogeneous] = false then 1 else 0, Int64.Type),
    Flags2 = Table.AddColumn(Flags1, "CREAMING", each if [cream_unsh_present] = null then null else if [cream_unsh_present] = true then 1 else 0, Int64.Type),
    Flags3 = Table.AddColumn(Flags2, "SERUM", each if [serum_unsh_present] = null then null else if [serum_unsh_present] = true then 1 else 0, Int64.Type),
    Flags4 = Table.AddColumn(Flags3, "SEDIMENT", each if [sed_unsh_present] = null then null else if [sed_unsh_present] = true then 1 else 0, Int64.Type),
    Flags5 = Table.AddColumn(Flags4, "GELLING", each if [gel_gelled] = null then null else if [gel_gelled] = true then 1 else 0, Int64.Type),
    Flags6 = Table.AddColumn(Flags5, "NON_HOMOG", each if [nh_lumps_present] = null then null else if [nh_lumps_present] = true then 1 else 0, Int64.Type),
    Flags7 = Table.AddColumn(Flags6, "PROTEIN_SAG", each if [psag_vertical_stripes_present] = null then null else if [psag_vertical_stripes_present] = true then 1 else 0, Int64.Type),
    Flags8 = Table.AddColumn(Flags7, "EXT_POWDER", each if [pwd_caking] = null then null else if [pwd_caking] <> null and [pwd_caking] <> "NONE" then 1 else 0, Int64.Type),
    Flags9 = Table.AddColumn(Flags8, "EXT_VMS", each if [vms_appearance_change] = null then null else if [vms_appearance_change] <> null and [vms_appearance_change] <> "NONE" then 1 else 0, Int64.Type),
    DefectIncidence = Table.UnpivotOtherColumns(Table.SelectColumns(Flags9, {"observationId", "versionNo", "projectCode", "arNumber", "trialNumber", "variantNumber", "sampleCode", "timePointCode", "conditionCode", "observedAt", "HOMOG", "CREAMING", "SERUM", "SEDIMENT", "GELLING", "NON_HOMOG", "PROTEIN_SAG", "EXT_POWDER", "EXT_VMS"}),
        {"observationId", "versionNo", "projectCode", "arNumber", "trialNumber", "variantNumber", "sampleCode", "timePointCode", "conditionCode", "observedAt"}, "domainCode", "defectPresent"),

    // ---- plan progress: plan cells x captured observations
    TimePointOffsets = #table({"timePointCode", "offsetDays"}, {
            {"T0", 0},
            {"1D", 1},
            {"1W", 7},
            {"2W", 14},
            {"1M", 30},
            {"2M", 61},
            {"3M", 91},
            {"4M", 122},
            {"6M", 182},
            {"9M", 273},
            {"12M", 365},
            {"15M", 456},
            {"18M", 548}
        }),
    PlanCells0 = Table.ExpandListColumn(Table.ExpandListColumn(Reference_Plans, "conditions"), "timePoints"),
    PlanCells1 = Table.RenameColumns(PlanCells0, {{"conditions", "conditionCode"}, {"timePoints", "timePointCode"}}),
    PlanCells2 = Table.NestedJoin(PlanCells1, {"timePointCode"}, TimePointOffsets, {"timePointCode"}, "Off", JoinKind.LeftOuter),
    PlanCells3 = Table.AddColumn(Table.ExpandTableColumn(PlanCells2, "Off", {"offsetDays"}), "dueDate", each Date.AddDays(Date.From([validFrom]), [offsetDays]), type date),
    Captured = Table.Group(ObservationCurrent, {"arNumber", "timePointCode", "conditionCode"}, {{"capturedCount", each Table.RowCount(_), Int64.Type}, {"firstCapturedAt", each List.Min([observedAt]), type datetimezone}}),
    PlanCells4 = Table.NestedJoin(PlanCells3, {"arNumber", "timePointCode", "conditionCode"}, Captured, {"arNumber", "timePointCode", "conditionCode"}, "Cap", JoinKind.LeftOuter),
    PlanCells5 = Table.ExpandTableColumn(PlanCells4, "Cap", {"capturedCount", "firstCapturedAt"}),
    PlanProgress = Table.AddColumn(PlanCells5, "cellStatus", each
        if [capturedCount] <> null and [capturedCount] > 0 then "CAPTURED"
        else if Duration.Days(DateTime.Date(DateTime.LocalNow()) - [dueDate]) > 7 then "OVERDUE"
        else if Duration.Days(DateTime.Date(DateTime.LocalNow()) - [dueDate]) >= -7 then "DUE"
        else "PLANNED", type text),

    // ---- media coverage
    MediaAsset = Table.TransformColumnTypes(ReadFolder("media_asset"), {{"versionNo", Int64.Type}, {"sizeBytes", Int64.Type}, {"durationS", type number}}),
    MediaAssetCurrent = Table.Join(MediaAsset, {"observationId", "versionNo"}, CurrentKeys, {"observationId", "versionNo"}, JoinKind.Inner),
    MediaCoverage = Table.Group(MediaAssetCurrent, {"observationId", "versionNo", "projectCode", "arNumber", "sampleCode", "timePointCode", "conditionCode"}, {
        {"mediaFiles", each Table.RowCount(_), Int64.Type},
        {"photos", each Table.RowCount(Table.SelectRows(_, each [mediaType] = "PHOTO")), Int64.Type},
        {"videos", each Table.RowCount(Table.SelectRows(_, each [mediaType] = "VIDEO")), Int64.Type},
        {"hasOverviewPhoto", each Table.RowCount(Table.SelectRows(_, each [fieldCode] = "general_overview_photo")) > 0, type logical},
        {"totalBytes", each List.Sum([sizeBytes]), Int64.Type}}),

    // ---- audit trail
    AuditLog = Table.TransformColumnTypes(ReadFolder("audit_log"), {{"eventTime", type datetimezone}})
in
    ObservationFlatExpanded
